package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.person.Patron;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Statement;
import net.officefloor.hq.app.person.Watch;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.role.Delegation;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

/**
 * A sheet as it stood at the end of an as-of date, for a user's screen while they view it so: its rows as
 * the changes made while the sheet's today was on or before that date left them, a later change not
 * counting, and the date standing in for the sheet's today. Each list is in the order the screen reads the
 * live one in.
 */
@Component
@Transactional(readOnly = true)
public class AsOf {

    /** The header a screen viewing the sheet as of a date (YYYY-MM-DD) sends with each request. */
    public static final String HEADER = "X-As-Of";

    private final History history;
    private final SheetRepository sheets;

    public AsOf(History history, SheetRepository sheets) {
        this.history = history;
        this.sheets = sheets;
    }

    /** The sheet as of the date, its today the date, its parent the one it has now; as it was started when no change to it counts by then. */
    public Sheet sheet(String sheetId, LocalDate asOf) {
        Sheet now = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        Sheet then = history.findAsOf(Sheet.class, sheetId, sheetId, asOf)
                .orElseGet(() -> new Sheet(sheetId, now.getCreatedBy(), now.getCreatedAt(), asOf));
        then.setToday(asOf);
        // the parent is not dated: the sheet names the one it names now
        then.setParent(now.getParent());
        return then;
    }

    /** The sheet's today as of the date: the date itself. */
    public LocalDate today(String sheetId, LocalDate asOf) {
        sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        return asOf;
    }

    /** The people, in list order: by their position (those kept before positions, by id). */
    public List<Person> people(String sheetId, LocalDate asOf) {
        return sorted(Person.class, sheetId, asOf, Comparator.comparing((Person p) -> p.getPosition() == null
                ? p.getId() : p.getPosition()).thenComparing(Person::getId));
    }

    /** The claims as listed: newest first. */
    public List<Claim> claims(String sheetId, LocalDate asOf) {
        return sorted(Claim.class, sheetId, asOf, Comparator.comparingLong(Claim::getListOrder).reversed());
    }

    /** The rates, by grade. */
    public List<Rate> rates(String sheetId, LocalDate asOf) {
        return sorted(Rate.class, sheetId, asOf, Comparator.comparing(Rate::getGrade));
    }

    /** The periods, by from-date. */
    public List<Period> periods(String sheetId, LocalDate asOf) {
        return sorted(Period.class, sheetId, asOf, Comparator.comparing(Period::getFromDate));
    }

    /** The statements, in the order they were taken. */
    public List<Statement> statements(String sheetId, LocalDate asOf) {
        return sorted(Statement.class, sheetId, asOf, Comparator.comparing(Statement::getId));
    }

    /** The patrons named, in the order they were named. */
    public List<Patron> patrons(String sheetId, LocalDate asOf) {
        return sorted(Patron.class, sheetId, asOf, Comparator.comparing(Patron::getId));
    }

    /** The watches kept, in the order they were started. */
    public List<Watch> watches(String sheetId, LocalDate asOf) {
        return sorted(Watch.class, sheetId, asOf, Comparator.comparing(Watch::getId));
    }

    /** The roles given, by user name. */
    public List<SheetRole> roles(String sheetId, LocalDate asOf) {
        return sorted(SheetRole.class, sheetId, asOf, Comparator.comparing(SheetRole::getUserName));
    }

    /** The delegations, in the order they were made. */
    public List<Delegation> delegations(String sheetId, LocalDate asOf) {
        return sorted(Delegation.class, sheetId, asOf, Comparator.comparing(Delegation::getId));
    }

    private <T> List<T> sorted(Class<T> type, String sheetId, LocalDate asOf, Comparator<T> order) {
        sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        return history.listAsOf(type, sheetId, asOf).stream().sorted(order).toList();
    }
}
package net.officefloor.hq.app.history;

import com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import jakarta.persistence.PostPersist;
import jakarta.persistence.PostRemove;
import jakarta.persistence.PostUpdate;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.person.Patron;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Statement;
import net.officefloor.hq.app.person.Watch;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.role.Delegation;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import tools.jackson.databind.DeserializationFeature;
import tools.jackson.databind.json.JsonMapper;

/**
 * The versions of a sheet, its people, their claims, its rates, its periods, the statements taken, the
 * patrons named, the watches kept, the roles given and the delegations made: each change keeps the state it left the
 * row in, with the sheet's today when it was made, so the rows can be read back as of a date — as the
 * changes made while the sheet's today was on or before it left them, each row's latest such change by the
 * order they were made, a change made later not counting whatever its today.
 * Kept by the entities' listener once the change is written, in the same transaction.
 */
@Component
public class History {

    private final JdbcTemplate jdbc;
    private final JsonMapper json = JsonMapper.builder()
            .changeDefaultVisibility(v -> v.withVisibility(PropertyAccessor.ALL, Visibility.NONE)
                    .withVisibility(PropertyAccessor.FIELD, Visibility.ANY))
            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .build();

    public History(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @PostPersist
    @PostUpdate
    public void saved(Object entity) {
        keep(entity, json.writeValueAsString(entity));
    }

    @PostRemove
    public void removed(Object entity) {
        keep(entity, null);
    }

    /** Keep the sheet's state now: for a change Hibernate does not see as an update of the sheet itself
     *  (its dated settings). */
    public void keep(Sheet sheet) {
        saved(sheet);
    }

    private void keep(Object entity, String state) {
        String sheetId;
        String entityId;
        if (entity instanceof Sheet sheet) {
            sheetId = sheet.getId();
            entityId = sheet.getId();
        } else if (entity instanceof Claim claim) {
            sheetId = claim.getSheetId();
            entityId = String.valueOf(claim.getId());
        } else if (entity instanceof Person person) {
            sheetId = person.getSheetId();
            entityId = String.valueOf(person.getId());
        } else if (entity instanceof Rate rate) {
            sheetId = rate.getSheetId();
            entityId = String.valueOf(rate.getId());
        } else if (entity instanceof Period period) {
            sheetId = period.getSheetId();
            entityId = String.valueOf(period.getId());
        } else if (entity instanceof Statement statement) {
            sheetId = statement.getSheetId();
            entityId = String.valueOf(statement.getId());
        } else if (entity instanceof Patron patron) {
            sheetId = patron.getSheetId();
            entityId = String.valueOf(patron.getId());
        } else if (entity instanceof Watch watch) {
            sheetId = watch.getSheetId();
            entityId = String.valueOf(watch.getId());
        } else if (entity instanceof SheetRole role) {
            sheetId = role.getSheetId();
            entityId = String.valueOf(role.getId());
        } else if (entity instanceof Delegation delegation) {
            sheetId = delegation.getSheetId();
            entityId = String.valueOf(delegation.getId());
        } else {
            throw new IllegalArgumentException("No history kept of " + entity.getClass());
        }
        LocalDate today = entity instanceof Sheet sheet ? sheet.getToday()
                : jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId).stream()
                        .filter(Objects::nonNull).findFirst().map(Date::toLocalDate).orElse(null);
        if (today == null) {
            return;
        }
        jdbc.update("INSERT INTO entity_version (sheet_id, kind, entity_id, recorded_on, state) VALUES (?, ?, ?, ?, ?)",
                sheetId, entity.getClass().getSimpleName(), entityId, Date.valueOf(today), state);
    }

    /** The sheet's rows of a kind as of a date, by id in the order first kept: each one's latest version made
     *  while the sheet's today was on or before it; none for a row removed then or not yet made. */
    public <T> Map<String, T> asOf(Class<T> type, String sheetId, LocalDate date) {
        Map<String, String> latest = new LinkedHashMap<>();
        jdbc.query("SELECT entity_id, state FROM entity_version WHERE sheet_id = ? AND kind = ? AND recorded_on <= ?"
                + " ORDER BY id", rs -> {
                    latest.put(rs.getString(1), rs.getString(2));
                }, sheetId, type.getSimpleName(), Date.valueOf(date));
        Map<String, T> rows = new LinkedHashMap<>();
        latest.forEach((id, state) -> {
            if (state != null) {
                rows.put(id, json.readValue(state, type));
            }
        });
        return rows;
    }

    /** The sheet's rows of a kind as of a date, in the order first kept. */
    public <T> List<T> listAsOf(Class<T> type, String sheetId, LocalDate date) {
        return List.copyOf(asOf(type, sheetId, date).values());
    }

    /** A row as of a date; none when it was not made by then, or removed. */
    public <T> Optional<T> findAsOf(Class<T> type, String sheetId, Object id, LocalDate date) {
        return Optional.ofNullable(asOf(type, sheetId, date).get(String.valueOf(id)));
    }
}
